BEGIN TRANSACTION READ ONLY;
WITH selected(catalog_id,engine_id,slug,version) AS (VALUES (374,'technology.storage-conversion','storage-conversion-calculator',1),(370,'technology.bandwidth','bandwidth-calculator',1),(371,'technology.download-time','download-time-calculator',1),(372,'technology.upload-time','upload-time-calculator',1),(373,'technology.data-transfer','data-transfer-calculator',1),(432,'conversion.time','time-converter',1),(440,'conversion.frequency','frequency-converter',1),(434,'conversion.data-storage','data-storage-converter',1),(423,'conversion.length','length-converter',1),(424,'conversion.area','area-converter',1),(425,'conversion.volume','volume-converter',1),(428,'conversion.speed','speed-converter',1),(438,'conversion.force','force-converter',1),(437,'conversion.density','density-converter',1),(439,'conversion.torque','torque-converter',1),(429,'conversion.pressure','pressure-converter',1),(430,'conversion.energy','energy-converter',1),(431,'conversion.power','power-converter',1),(433,'conversion.angle','angle-converter',1),(427,'conversion.temperature','temperature-converter',1))
SELECT jsonb_build_object('observed_at',now(),'project_expected','zpwpstsvztyshcnwdfye','transaction_read_only',current_setting('transaction_read_only'),
'candidates',(SELECT jsonb_agg(jsonb_build_object('catalog_id',s.catalog_id,'engine_id',s.engine_id,'slug',s.slug,'expected_version',s.version,'hosted_match',c.id IS NOT NULL,'hosted_version',c.version,'lifecycle',c.lifecycle,'risk_class',c.risk_class,'reviewer_assigned',c.reviewer_id IS NOT NULL,'source_count',c.source_count,'canonical',c.metadata->'canonical','certification',c.metadata->'certification','qa_rows',(SELECT count(*) FROM public.calculator_qa_checks q WHERE q.calculator_id=c.id),'source_rows',(SELECT count(*) FROM public.calculator_source_evidence e WHERE e.calculator_id=c.id),'reviewer_active_capable',EXISTS(SELECT 1 FROM public.platform_admins a WHERE a.user_id=c.reviewer_id AND a.active AND a.role IN ('owner','admin','reviewer')))) FROM selected s LEFT JOIN public.calculator_catalog_admin c ON c.calculator_key=s.engine_id AND c.version=s.version AND c.slug=s.slug),
'governance_tables',(SELECT jsonb_agg(t) FROM (SELECT c.relname,c.relrowsecurity AS rls_enabled,c.relforcerowsecurity AS force_rls,c.relacl::text AS acl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('calculator_catalog_admin','calculator_source_evidence','calculator_qa_checks','calculator_review_events','platform_admins') ORDER BY c.relname)t),
'policies',(SELECT jsonb_agg(t) FROM (SELECT tablename,policyname,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public' AND tablename IN ('calculator_catalog_admin','calculator_source_evidence','calculator_qa_checks','calculator_review_events','platform_admins') ORDER BY tablename,policyname)t),
'publication_functions',(SELECT jsonb_agg(t) FROM (SELECT p.proname,pg_get_function_identity_arguments(p.oid) AS arguments,p.prosecdef AS security_definer,pg_get_functiondef(p.oid) AS definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND (p.proname ~ 'calculator.*(publish|certif|lifecycle|revalid)' OR p.proname='list_published_calculator_manifest') ORDER BY p.proname)t),
'governance_triggers',(SELECT jsonb_agg(t) FROM (SELECT c.relname,t.tgname,t.tgenabled,t.tgdeferrable,t.tginitdeferred,pg_get_triggerdef(t.oid) AS definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal AND c.relname IN ('calculator_catalog_admin','calculator_source_evidence','calculator_qa_checks','platform_admins') ORDER BY c.relname,t.tgname)t)
) AS evidence;
COMMIT;
